    post_api_voice_oauth_token: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/x-www-form-urlencoded": {
                    /** @enum {string} */
                    grant_type: "authorization_code" | "refresh_token";
                    /** @description Avec `authorization_code` : le code reçu à l'autorisation */
                    code?: string;
                    /** @description Avec `authorization_code` : l'adresse de retour de l'autorisation, la même */
                    redirect_uri?: string;
                    /** @description Avec `authorization_code` : le vérificateur PKCE (43 à 128 caractères) dont le SHA-256 est le `code_challenge` de l'autorisation */
                    code_verifier?: string;
                    /** @description Avec `refresh_token` : le jeton de rafraîchissement reçu en dernier */
                    refresh_token?: string;
                    /** @description Authentification dans le corps (ou `Authorization: Basic`) */
                    client_id?: string;
                    /** @description Authentification dans le corps (ou `Authorization: Basic`) */
                    client_secret?: string;
                };
            };
        };
        responses: {
            /** @description Une paire de jetons. `Cache-Control: no-store` */
            200: {
                headers: {
                    /** @description `no-store` */
                    "Cache-Control"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example 3Qa5mVq1xT0Zb8nWc2YpLkR7sHdJ9eUfGhAoIiNtBvM */
                        access_token?: string;
                        /** @example Bearer */
                        token_type?: string;
                        /** @example 3600 */
                        expires_in?: number;
                        /** @example Zt4Lw9RkEoPq2YhXn6VbGcJdUaSf8MiH1TgNyQr0eKs */
                        refresh_token?: string;
                    };
                };
            };
            /** @description Erreur OAuth `{"error": "invalid_request" | "invalid_grant" | "unsupported_grant_type"}` */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example invalid_grant */
                        error?: string;
                    };
                };
            };
            /** @description Erreur OAuth `{"error": "invalid_client"}` : client inconnu, secret faux ou absent */
            401: {
                headers: {
                    /** @description `Basic realm="Repas"` */
                    "WWW-Authenticate"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example invalid_client */
                        error?: string;
                    };
                };
            };
            /** @description Commande vocale coupée (message `VOICE_DISABLED`) */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            429: components["responses"]["VoiceTokenRateLimited"];
        };
    };
    post_api_voice_alexa: {
        parameters: {
            query?: never;
            header: {
                /** @description Adresse de la chaîne de certificats d'Amazon (`https://s3.amazonaws.com/echo.api/…`) */
                SignatureCertChainUrl: string;
                /** @description Signature RSA SHA-256 du corps brut, en base64 */
                "Signature-256": string;
            };
            path?: never;
            cookie?: never;
        };
        /** @description La requête d'Alexa, telle qu'Amazon l'envoie (non modélisée ici : seuls `request.type`, `request.locale`, `request.intent` (et ses créneaux), `session.new`, `session.attributes.dialogue`, `session.user` et le jeton d'accès sont lus) */
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "version": "1.0",
                 *       "session": {
                 *         "new": true,
                 *         "user": {
                 *           "userId": "amzn1.ask.account.EXAMPLE",
                 *           "accessToken": "3Qa5mVq1xT0Zb8nWc2YpLkR7sHdJ9eUfGhAoIiNtBvM"
                 *         }
                 *       },
                 *       "request": {
                 *         "type": "IntentRequest",
                 *         "locale": "fr-FR",
                 *         "timestamp": "2026-10-25T12:00:00Z",
                 *         "intent": {
                 *           "name": "AddItemIntent",
                 *           "slots": {
                 *             "item": {
                 *               "name": "item",
                 *               "value": "du pain"
                 *             }
                 *           }
                 *         }
                 *       }
                 *     }
                 */
                "application/json": Record<string, never>;
            };
        };
        responses: {
            /** @description La réponse vocale d'Alexa (`SessionEndedRequest` : `response` vide). Avec la carte `LinkAccount` quand le compte n'est pas lié */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example 1.0 */
                        version?: string;
                        /** @description Seulement quand la séance reste ouverte : l'état du dialogue d'un produit inconnu (`dialogue`), `{}` quand il n'y en a pas. Alexa le rend dans `session.attributes` à la requête suivante */
                        sessionAttributes?: Record<string, never>;
                        response?: {
                            outputSpeech?: {
                                /** @example PlainText */
                                type?: string;
                                /** @example C'est noté : pain. */
                                text?: string;
                            };
                            /** @description Seulement quand la séance reste ouverte : ce qu'Alexa répète après un silence */
                            reprompt?: Record<string, never>;
                            /** @description `{"type": "LinkAccount"}` quand le compte n'est pas lié */
                            card?: Record<string, never>;
                            /** @example true */
                            shouldEndSession?: boolean;
                        };
                    };
                };
            };
            /** @description Requête qui ne prouve pas venir d'Alexa ou ne vise pas ce skill (message `INVALID_ALEXA_REQUEST`, sans autre détail) */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Commande vocale coupée (message `VOICE_DISABLED`) */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            429: components["responses"]["VoiceWebhookRateLimited"];
        };
    };
